/span&gt;&lt;span class=&quot;NormalTextRun SCXW208968338 BCX8&quot;&gt; to continuously raise the &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208968338 BCX8&quot;&gt;bar&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208968338 BCX8&quot;&gt;, and you &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208968338 BCX8&quot;&gt;don’t&lt;/span&gt; &lt;span class=&quot;NormalTextRun SCXW208968338 BCX8&quot;&gt;allow&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208968338 BCX8&quot;&gt; artificial boundaries&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208968338 BCX8&quot;&gt; to&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208968338 BCX8&quot;&gt; impede you from solving &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208968338 BCX8&quot;&gt;difficult &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW208968338 BCX8&quot;&gt;problems.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW208968338 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Responsibilities&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;:&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Design and implement robust,&amp;nbsp;testable,&amp;nbsp;high-performance systems and tools in Rust.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;Optimize existing software architectures to enhance speed and efficiency.&lt;/li&gt;
&lt;li&gt;Actively participate in all phases of the development lifecycle, including debugging and optimization, to ensure and elevate software quality.&lt;/li&gt;
&lt;li&gt;Stay informed about the latest advancements in Rust programming, security, and software design principles, helping to foster an environment of continuous learning and improvement.&lt;/li&gt;
&lt;li&gt;Give and receive peer feedback on a normal cadence as part of our review cycle&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Minimum Qualifications&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;:&lt;/span&gt;&lt;/strong&gt; &lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;5+ years of experience developing backend systems in a fast paced, high&lt;br&gt;performance team environment&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;3+ years of experience in relational databases such as Postgres&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;5&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;3+ years of experience with NoSQL databases such as Elasticsearch&lt;/span&gt;&lt;/li&gt;
